import{_ as a,o,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const g=JSON.parse('{"title":"第 22 章 行业路线图：从通用能力到行业工作流（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第22章 行业路线图：从通用能力到行业工作流（易懂版）.md","filePath":"easy/第22章 行业路线图：从通用能力到行业工作流（易懂版）.md"}'),n={name:"easy/第22章 行业路线图：从通用能力到行业工作流（易懂版）.md"};function s(l,t,i,d,h,u){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-22-章-行业路线图-从通用能力到行业工作流-易懂版" tabindex="-1">第 22 章 行业路线图：从通用能力到行业工作流（易懂版） <a class="header-anchor" href="#第-22-章-行业路线图-从通用能力到行业工作流-易懂版" aria-label="Permalink to &quot;第 22 章 行业路线图：从通用能力到行业工作流（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 22 章 行业路线图：从通用能力到行业工作流（完整版）](../../bluebook/第四篇 岗位与行业落地/第 22 章 行业路线图：从通用能力到行业工作流.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>从&quot;个人会用 AI&quot;到&quot;整个行业的工作方式被 AI 改造&quot;——看看你的行业能怎么走。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>电脑刚普及时，不是&quot;会打字就行&quot;，而是<strong>每个行业都长出自己的用法</strong>：会计用表格、作家用排版、医生用病历系统。</p><p>AI 也一样：<strong>通用能力是起点，行业化才是终点。</strong></p><h2 id="三个行业怎么落地-速查" tabindex="-1">三个行业怎么落地（速查） <a class="header-anchor" href="#三个行业怎么落地-速查" aria-label="Permalink to &quot;三个行业怎么落地（速查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>行业</th><th>典型 AI 应用</th><th>关键资产</th></tr></thead><tbody><tr><td><strong>内容行业</strong></td><td>选题库、初稿生成、多平台改写、数据复盘</td><td>选题库 + 风格规范 + 爆款复盘库</td></tr><tr><td><strong>教育培训</strong></td><td>备课资料、课件初稿、习题生成、学情分析</td><td>课程体系 + 题库 + 学生档案</td></tr><tr><td><strong>电商零售</strong></td><td>商品文案、客服话术、选品分析、竞品监控</td><td>商品库 + 话术库 + 数据看板</td></tr></tbody></table><h2 id="行业化的四步方法" tabindex="-1">行业化的四步方法 <a class="header-anchor" href="#行业化的四步方法" aria-label="Permalink to &quot;行业化的四步方法&quot;">​</a></h2><ol><li><strong>盘点流程</strong>：画出你行业一条核心业务线的完整流程；</li><li><strong>找 AI 插入点</strong>：哪个环节最耗时、最重复、最标准化——AI 就从那介入；</li><li><strong>积累资产</strong>：每次用 AI 的产出（模板、话术、数据）<strong>沉淀成行业资产库</strong>；</li><li><strong>沉淀工作流</strong>：把&quot;人+AI&quot;配合的固定套路固化成团队标准流程。</li></ol><h2 id="为什么很多-ai-项目会失败" tabindex="-1">为什么很多 AI 项目会失败？ <a class="header-anchor" href="#为什么很多-ai-项目会失败" aria-label="Permalink to &quot;为什么很多 AI 项目会失败？&quot;">​</a></h2><ul><li>❌ 只买工具不改造流程——<strong>工具是新的，做法还是旧的</strong>；</li><li>❌ 只让个人用，不做组织沉淀——<strong>人走了，经验也带走了</strong>；</li><li>❌ 一上来就追求&quot;全自动&quot;——<strong>先人机配合，再逐步自动化</strong>。</li></ul><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p>你开网店：&quot;把客服最高频的 20 个问题做成话术库，用 AI 生成初稿、我审核后入库；再让 AI 每周出一份&#39;差评分析&#39;，沉淀成改进清单。&quot; 这就是<strong>从通用到行业</strong>的一小步：话术库就是你的行业资产。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 追求一步到位——<strong>行业改造是渐进式的，先跑通一条线</strong>；</li><li>❌ 只积累不用——<strong>资产库要进流程，否则只是收藏</strong>；</li><li>❌ 忽略人审——<strong>行业里出错的代价高，关键输出必须人把关</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>行业落地 = 找流程里的 AI 插入点 + 积累行业资产 + 固化成工作流。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>画出你行业<strong>一条核心业务线</strong>，标出最耗时的环节——<strong>那就是你行业化的第一站。</strong></p><p>👉 <a href="./../easy/">回到易懂版首页 🏠</a></p>',22)])])}const c=a(n,[["render",s]]);export{g as __pageData,c as default};
